class Solution {
    public int[][] kClosest(int[][] points, int K) {
        PriorityQueue<int[]> maxHeap = 
            new PriorityQueue<>((a,b) -> (getDistance(b) - getDistance(a)));
        int[][] result = new int[K][2];

        for(int i = 0; i < K; i++){
            maxHeap.offer(points[i]);
        }

        for(int i = K; i < points.length; i++){
            if(getDistance(maxHeap.peek()) > getDistance(points[i])){
                maxHeap.poll();
                maxHeap.offer(points[i]);
            }
        }

        for(int i = 0; i < K; i++){
            result[i] = maxHeap.poll();
        }

        return result;
    }

    public int getDistance(int a[]){
        return (a[0] * a[0]) + (a[1] * a[1]);
    }
}

class Solution {
public:
    static bool comparator(pair<int, int> f, pair<int, int> s) {
        return (f.second < s.second);
    }
    vector<vector<int>> kClosest(vector<vector<int>>& points, int K) {
        vector<pair<int, int>> distance;
        for (int i = 0; i < points.size(); i++) {
            int x = points[i][0], y = points[i][1];
            distance.push_back(make_pair(i, abs(x*x + y*y)));
        }
        sort(distance.begin(), distance.end(), comparator);
        vector<vector<int>> ans;
        for (int i = 0; i < K; i++) {
            vector<int> point;
            point.push_back(points[distance[i].first][0]);
            point.push_back(points[distance[i].first][1]);
            ans.push_back(point);
        }
        return ans;
    }
};

