class Solution {
public:
    vector<vector<int>> kClosest(vector<vector<int>>& points, int k) {
        priority_queue<pair<int,pair<int,int>>> maxh;
        for(auto it:points)
        {
            maxh.push({it[0]*it[0]+it[1]*it[1],{it[0],it[1]}});
            if(maxh.size()>k)
                maxh.pop();
        }
        vector<vector<int>> ans;
        while(!maxh.empty())
        {
            ans.push_back({maxh.top().second.first,maxh.top().second.second});
            maxh.pop();
        }
        return ans;
    }
};

class Solution(object):
    def kClosest(self, points, k):
        """
        :type points: List[List[int]]
        :type k: int
        :rtype: List[List[int]]
        """
        dists = [(-p[0] * p[0] - p[1] * p[1], p) for p in points[:k]]
        heapq.heapify(dists)
        for p in points[k:]:
            heapq.heappushpop(dists, (-p[0] * p[0] - p[1] * p[1], p))
        return list(map(lambda x: x[1], dists))
